export function createOverview({ data, tag, link, fmt }) {
  function art() {
    return `<div class="hero-art"><span class="art-label">THE WATER–ENERGY CONNECTION</span><svg viewBox="0 0 460 300" role="img" aria-label="Concept diagram: IT servers use electricity, produce heat, and connect to cooling and power-generation water use."><defs><radialGradient id="halo"><stop stop-color="#3c8b8e" stop-opacity=".25"/><stop offset="1" stop-color="#10242d" stop-opacity="0"/></radialGradient><linearGradient id="drop" x2="1" y2="1"><stop stop-color="#b7f3e6"/><stop offset="1" stop-color="#4b979e"/></linearGradient><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" fill="none" stroke="#294955" stroke-width=".5" opacity=".4"/></pattern></defs><ellipse cx="236" cy="152" rx="210" ry="135" fill="url(#halo)"/><rect x="20" y="10" width="420" height="275" fill="url(#grid)"/><ellipse cx="236" cy="150" rx="142" ry="97" fill="none" stroke="#35545d" stroke-dasharray="3 6"/><ellipse cx="236" cy="150" rx="112" ry="112" fill="none" stroke="#25424b"/><ellipse cx="236" cy="150" rx="92" ry="58" fill="none" stroke="#3c6970"/><path d="M235 56C220 86 180 120 180 154a55 55 0 0 0 110 0c0-34-40-68-55-98Z" fill="url(#drop)" opacity=".95"/><path d="M198 156c0 24 15 40 36 40" fill="none" stroke="#c7fff1" stroke-opacity=".6" stroke-width="3" stroke-linecap="round"/><path d="M180 141H107M291 153h77M234 210v38" stroke="#73a4aa" stroke-dasharray="3 4"/><g fill="#122a34" stroke="#3a626a"><rect x="27" y="103" width="111" height="56" rx="7"/><rect x="330" y="127" width="112" height="56" rx="7"/><rect x="182" y="236" width="108" height="45" rx="7"/></g><g font-family="sans-serif" text-anchor="middle"><text x="83" y="125" fill="#8ce2da" font-size="10">ELECTRICITY</text><text x="83" y="143" fill="#8da8b6" font-size="9">power-generation water</text><text x="385" y="149" fill="#8ce2da" font-size="10">COOLING</text><text x="385" y="168" fill="#8da8b6" font-size="9">on-site consumption</text><text x="236" y="263" fill="#b9d2db" font-size="10">AI & IT WORKLOADS</text></g><g fill="#a2e3db"><circle cx="105" cy="141" r="3"/><circle cx="369" cy="153" r="3"/><circle cx="234" cy="220" r="3"/></g></svg><div class="art-bottom">Conceptual system boundary · not a geographic map</div></div>`;
  }
  function overview() {
    return `<section class="hero"><div><div class="eyebrow">AI water evidence, explained</div><h1>See what AI water<br>headlines <em>leave out.</em></h1><p class="lede">Compare published disclosures. Spot a missing boundary. Try a cooling trade-off with the assumptions visible. No account or API key.</p><div class="buttons"><a class="btn" href="#challenge">Understand one claim <span>↗</span></a><a class="btn ghost" href="#lab">Try a cooling trade-off</a></div></div>${art()}</section><div class="trustbar"><span>Primary sources, traceable claims</span><span>Reported evidence ≠ scenarios</span><span>No universal water-per-prompt figure</span></div><section class="cols quick-start"><article class="card"><div class="eyebrow">A useful first question</div><h2>Same unit. Same meaning?</h2><p>A water total can cover cooling, a data-centre fleet or an entire company. Withdrawal and consumption are different quantities. The year matters too.</p><a class="small-link" href="#challenge">Try a source-backed comparison ↗</a></article><article class="card"><div class="eyebrow">An example, not a measurement</div><h2>Less direct water can mean more electricity.</h2><p>Our hypothetical comparison separates both water pathways. Change one assumption, inspect the result, then share the inputs with it.</p><a class="small-link" href="#lab">Open the guided cooling example ↗</a></article></section><section class="cols"><article class="card"><div class="sectionhead"><div><h2>The scale is changing.</h2><p>Global data-centre electricity demand · TWh/year</p></div>${tag("SOURCE: IEA 2026", "blue")}</div><svg class="chart" viewBox="0 0 560 230" role="img" aria-label="IEA estimates global data-centre electricity demand at 485 TWh in 2025 and projects 950 TWh in 2030."><g class="gridline"><path d="M48 185H535M48 105H535M48 25H535"/></g><g fill="#738f9d" font-size="10"><text x="12" y="189">0</text><text x="5" y="109">500</text><text x="0" y="29">1,000</text></g><rect x="123" y="107.4" width="105" height="77.6" fill="#416679" rx="4"/><rect x="335" y="33" width="105" height="152" fill="#8ce2da" rx="4"/><g text-anchor="middle"><text x="175" y="95" fill="#afc7d2" font-size="23">485</text><text x="387" y="23" fill="#b0eee7" font-size="23">950</text><text x="175" y="210" fill="#a1b8c4" font-size="11">2025 estimate</text><text x="387" y="210" fill="#a1b8c4" font-size="11">2030 projection</text></g></svg><p class="source-note">${link("IEA26")} · C01–C02 · Two source endpoints, not an invented annual trajectory. Electricity is not water; AI is one part of data-centre demand.</p><div class="insight">So what? Growth makes cooling and power choices worth examining. This chart does not establish a global AI water total.</div></article><article class="card"><div class="eyebrow">Follow the physical chain</div><h2>Two paths to water use.</h2><div class="mechanism"><div><b>▤</b>IT work</div><span>→</span><div><b>ϟ</b>Electricity</div><span>→</span><div><b>≈</b>Heat</div></div><h3>01 / At the data centre</h3><p class="subtle">Some cooling systems consume water on site, often through evaporation. Heat rejection design matters.</p><hr class="divider"><h3>02 / At the power source</h3><p class="subtle">Producing electricity can also consume water. The amount and location depend on the generation and cooling mix.</p><a class="small-link" href="#evidence">Understand the accounting boundary ↗</a></article></section><section class="feature-row"><article class="card"><div class="index">01 / EXPERIMENT</div><h3>Less direct water. More power?</h3><p>Test when lower on-site water demand also lowers total operational consumption.</p><a href="#lab" class="small-link">Compare the trade-off ↗</a></article><article class="card"><div class="index">02 / INVESTIGATE</div><h3>India, beyond the average.</h3><p>Explore reported state/UT groundwater conditions. Regional context, without unsupported facility claims.</p><a href="#india" class="small-link">Open the India observatory ↗</a></article><article class="card"><div class="index">03 / ACT</div><h3>From concern to better choices.</h3><p>Examine solutions, constraints and what operators and communities should monitor.</p><a href="#solutions" class="small-link">Read the playbook ↗</a></article></section><article class="card evidence-updates"><h2>What changed in the evidence?</h2><p>Company reporting boundaries were clarified. A seasonal NREL source candidate was reviewed without inventing monthly numeric data. The calculator now shares complete assumptions.</p><a href="https://github.com/purushotmanmooper96-bit/thirstyai/blob/main/CHANGELOG.md">Read dated updates and validation status ↗</a></article><div class="callout">Coverage today: <strong>${data.sources.length} registered documents · ${data.claims.length} numerical claims · 36 state/UT records.</strong> Company-reported location records: <strong>${data.locations.length}</strong>; independent remeasurements: <strong>0</strong>. <a href="#companies">Compare disclosures</a> · <a href="#locations">Inspect regional context</a>. A global AI water total is not estimated in this release.</div>`;
  }
  return overview;
}
